def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    if not b_intervals:
        return a_intervals

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    result = []

    for a_start, a_end in a_intervals:
        current_start = a_start

        # Process each interval in b that could overlap with [current_start, a_end)
        for b_start, b_end in merged_b:
            # If b interval is completely before current segment, skip
            if b_end <= current_start:
                continue
            # If b interval is completely after current segment, we're done
            if b_start >= a_end:
                break

            # There's an overlap
            # Add the part of a before b (if any)
            if current_start < b_start:
                result.append([current_start, b_start])

            # Move current_start past the b interval
            current_start = max(current_start, b_end)

        # Add any remaining part of a after processing all b intervals
        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge touching intervals in result
    if not result:
        return []

    merged_result = [result[0]]
    for start, end in result[1:]:
        if start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

